  private int level;
  private int hp;

  public Player(String name, int level) {
    this.name = name;
    this.level = level;
    this.hp = 100;
  }

  public String getName() {
    return name;
  }

  public int getLevel() {
    return level;
  }

  public int getHp() {
    return hp;
  }

  public void takeDamage(int amount) {
    hp = hp - amount;
  }

  public void heal(int amount) {
    hp = hp + amount;
  }

  public void levelUp() {
    level = level + 1;
  }

  public boolean isAlive() {
    return hp > 0;
  }

  public String toString() {
    return name + " (level " + level + ", " + hp + " hp)";
  }
}

