class Dragon {
  private String name;
  private int level;
  private boolean canBreatheFire;

  public Dragon(String dragonName, int dragonLevel) {
    name = dragonName;
    level = dragonLevel;
    canBreatheFire = level >= 70;
  }

  public String getName() {
    return name;
  }

  public int getLevel() {
    return level;
  }

  public boolean isFireBreather() {
    return canBreatheFire;
  }

  public void attack() {
    if (canBreatheFire) {
      System.out.println(">>>>>>>>>>");
      System.out.println(">>>>>>>>>>>>>>");
      System.out.println(">>>>>>>>>>>>>>");
      System.out.println(">>>>>>>>>>");
    } else {
      System.out.println("~ ~ ~");
    }
  }

  public void gainExperience() {
    level = level + 10;
    canBreatheFire = level >= 70;
  }
}

